   (	"LOG_ID" NUMBER NOT NULL ENABLE, 
	"AGENT_ACCOUNT_ID" NUMBER, 
	"AGENT_CHANNEL_ID" NUMBER, 
	"AGENT_CHANNEL_CODE" VARCHAR2(10), 
	"AGENT_CHANNEL_NAME" VARCHAR2(300), 
	"AGENT_CHANNEL_PHONE" VARCHAR2(20), 
	"AGENT_PROVINCE_CODE" VARCHAR2(10), 
	"AGENT_PROVINCE_NAME" VARCHAR2(300), 
	"AGENT_DISTRICT_CODE" VARCHAR2(10), 
	"AGENT_DISTRICT_NAME" VARCHAR2(300), 
	"AGENT_WARD_CODE" VARCHAR2(10), 
	"AGENT_WARD_NAME" VARCHAR2(300), 
	"AGENT_ADDRESS" VARCHAR2(300), 
	"TRANSACTION_ID" NUMBER, 
	"PROCESS_CODE" VARCHAR2(6), 
	"PROCESS_CODE_NAME" VARCHAR2(100), 
	"TRANS_TYPE_ID" NUMBER, 
	"TRANS_TYPE_NAME" VARCHAR2(100), 
	"TRANS_DATE" DATE, 
	"TRANS_AMOUNT" NUMBER, 
	"TRANS_FEE" NUMBER, 
	"TRANS_DISCOUNT" NUMBER, 
	"TRANS_TOTAL_AMOUNT" NUMBER, 
	"TRANS_FROM_ACCOUNT_ID" NUMBER, 
	"TRANS_FROM_PHONE" VARCHAR2(20), 
	"TRANS_TO_ACCOUNT_ID" NUMBER, 
	"TRANS_TO_PHONE" VARCHAR2(20), 
