	"ACCOUNTING_TYPE_ID" NUMBER(22,0), 
	"REVENUE_TYPE" VARCHAR2(100), 
	"SUMMARY_DATE" DATE, 
	"TRANS_FROM_PHONE" VARCHAR2(20), 
	"TRANS_TO_PHONE" VARCHAR2(20), 
	"ROLE_NAME" VARCHAR2(100), 
